//! raw-ffi develop statuses the API acts on (#5499), single-sourced from
//! raw-core's `Error`.
use raw_core::Error;

pub fn emit_ts() -> String {
    format!(
        "// Generated by codegen --schema ffi-status. Do not edit.\n\n/** `maple_render_develop_jpeg_to_file`: the decoder has no definition for the camera body. */\nexport const RC_UNSUPPORTED_CAMERA = {};\n/** How raw-core's unsupported-camera error message begins. */\nexport const UNSUPPORTED_CAMERA_MESSAGE_PREFIX = '{}';\n",
        Error::UNSUPPORTED_CAMERA_FFI_CODE,
        Error::UNSUPPORTED_CAMERA_MESSAGE_PREFIX
    )
}
